import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BN3Eol-0.js";const b=JSON.parse('{"title":"UXS-005 — Earth Orbit Viewer","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-005.md","filePath":"uxs/UXS-005.md"}'),n={name:"uxs/UXS-005.md"};function r(s,e,l,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="uxs-005-—-earth-orbit-viewer" tabindex="-1">UXS-005 — Earth Orbit Viewer <a class="header-anchor" href="#uxs-005-—-earth-orbit-viewer" aria-label="Permalink to &quot;UXS-005 — Earth Orbit Viewer&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Visual fidelity · Verified against prototype (P05_earth-orbit.html) IA anchor · §surfaces/earth · §topbar-patterns · §shared-tokens Related PRD · PRD-005</p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p>The Earth orbit viewer is a single logarithmic-scale canvas. This UXS defines the scale function, object appearance, regime labels, and detail panel.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li>The logarithmic scale must be legible without prior knowledge — labels explain the non-linearity</li><li>Object dots are small; labels are the signal</li><li>Regime bands are subtle — they frame, not overwhelm</li><li>The detail panel is the same component as explore and missions screens</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>In scope: nav bar, canvas (scale, objects, regime labels, regime bands), detail panel. Non-goals: object animation (static view — objects don&#39;t move). Boundary note: click detection logic belongs in the screen module.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Dark only.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><h3 id="inherited-from-ia" tabindex="-1">Inherited from IA <a class="header-anchor" href="#inherited-from-ia" aria-label="Permalink to &quot;Inherited from IA&quot;">​</a></h3><p>All shared tokens.</p><h3 id="defined-here" tabindex="-1">Defined here <a class="header-anchor" href="#defined-here" aria-label="Permalink to &quot;Defined here&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>regime-leo:    rgba(75,156,211,0.06)   Low Earth Orbit band</span></span>
<span class="line"><span>regime-meo:    rgba(80,112,255,0.05)   Medium Earth Orbit band</span></span>
<span class="line"><span>regime-geo:    rgba(255,200,80,0.06)   Geostationary band</span></span>
<span class="line"><span>regime-cis:    rgba(255,255,255,0.03)  Cislunar band</span></span>
<span class="line"><span>scale-fn:      altToVis(alt_km) = 38 + 54 * log10(1 + alt_km/100)   (px from Earth surface)</span></span>
<span class="line"><span>object-dot:    4–6px radius, object-specific colour</span></span>
<span class="line"><span>object-label:  Space Mono 11px, object colour, left of dot</span></span></code></pre></div><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>Vertical canvas filling the viewport (minus nav bar). Earth at bottom. Scale labels on left edge. Regime band labels on right edge. Objects as dots at their computed vertical position. Detail panel right 400px on object click.</p><h2 id="object-index" tabindex="-1">Object index <a class="header-anchor" href="#object-index" aria-label="Permalink to &quot;Object index&quot;">​</a></h2><p>The left-edge INDEX lists the launch sites and the orbital objects. Every row leads with the round photo of its panel&#39;s image (L45-T2, <a href="./decisions/UXD-025-lists-carry-a-round-photo">UXD-025</a>: 73 of 73); a launch site&#39;s ring is its nation&#39;s colour (the legend&#39;s; the dot of a row without a photo is that colour with a 1px light ring); an orbital object keeps its own object colour (teal drawn neutral); every row&#39;s meta line ends with <code>In orbit</code> or <code>On land</code> (<a href="./decisions/UXD-017-one-index-on-every-scale">UXD-017</a> amendment, C6). Under the search sit the All, In orbit and On land chips on one row and, beside the count, a FILTERS button: agency, era and status are behind it, closed at the start, and the button shows how many of them are on (C6-F, same amendment).</p><h2 id="museum-card" tabindex="-1">Museum card <a class="header-anchor" href="#museum-card" aria-label="Permalink to &quot;Museum card&quot;">​</a></h2><p>A museum pin opens its card (<code>MuseumPanel</code>): the place photo, the description, the website button and the real objects it shows. Each object row leads with the round photo of that object (L45-T4, <a href="./decisions/UXD-025-lists-carry-a-round-photo">UXD-025</a>: 86 of 88 holdings; the 2 holdings that are <code>/science/history/&lt;slug&gt;</code> pages keep the centred dot, so names line up); the ring is neutral, the row carries no agency. The name stays the link; the photo is decorative (<code>alt=&quot;&quot;</code>, lazy).</p><h2 id="welcome-hint" tabindex="-1">Welcome hint <a class="header-anchor" href="#welcome-hint" aria-label="Permalink to &quot;Welcome hint&quot;">​</a></h2><p>One dismissible line near the bottom centre (under the top row on touch): &quot;Zoom in to explore · drag to look around&quot; (<code>ExploreHint</code>, <code>surface_hint_zoom</code>, <a href="./decisions/UXD-027-explore-levels-one-table-glyphs-card-and-hint">UXD-027</a>). It is the same component as /explore&#39;s, mounted once in <code>SurfaceScene</code> for /earth, /moon, /mars and /venus: gone at the first wheel turn, pinch, tap or drag on the canvas, at its ×, or after 12 s, and shown again on the next visit. Showing a few site markers at the start zoom is not part of it.</p><h2 id="touch-gestures" tabindex="-1">Touch gestures <a class="header-anchor" href="#touch-gestures" aria-label="Permalink to &quot;Touch gestures&quot;">​</a></h2><p>The 3D view follows the same contract as /explore (<code>src/lib/three/touch-gestures.ts</code>): one finger orbits (a panorama only looks around), two fingers pinch to zoom and drag to pan, together; the canvas owns the touch (<code>touch-action: none</code>), so a gesture never scrolls the page. The same on /iss and /tiangong (OrbitControls: <code>ORBIT_CONTROLS_TOUCHES</code>, rotate / dolly-pan) and on /fly&#39;s 3D view. Intentionally without camera gestures: /fly&#39;s launch, coast and descent scenes (the flight director drives their camera; their canvases take no pointer events) and the fleet line-up (a fixed side view).</p><h2 id="orbit-ruler-and-bottom-left-column" tabindex="-1">Orbit ruler and bottom-left column <a class="header-anchor" href="#orbit-ruler-and-bottom-left-column" aria-label="Permalink to &quot;Orbit ruler and bottom-left column&quot;">​</a></h2><p>The orbit ruler, the locate chip and its folding, hover and click behaviour are specified in <a href="./UXS-014#the-orbit-ruler">UXS-014</a> (<a href="./decisions/UXD-024-orbit-ruler-one-row-draws-its-regime">UXD-024</a>). On /earth the chip and the ruler are one column at the lower left; MOON is drawn as a ring at the Moon ghost&#39;s orbit and L2 as pin rings on its residents.</p><h2 id="selected-orbiter" tabindex="-1">Selected orbiter <a class="header-anchor" href="#selected-orbiter" aria-label="Permalink to &quot;Selected orbiter&quot;">​</a></h2><p>An orbital object selected in the 3D view (ISS, Hubble and the rest) keeps the orbits in view: its dot, its ring, every other orbiter and the ruler stay drawn while it is selected, although the fly-in lands under one Earth radius (the rule is <code>orbitsInViewNext</code>, <code>surface-view-state.ts</code>). The selected object wears the outline pass, as on hover. With the panel open the view shifts so the object sits in the middle of the space the panel leaves (half the panel&#39;s width; a touch-portrait sheet shifts nothing), the same shift as on <code>/explore</code>. Closing the panel clears the selection (<a href="./decisions/UXD-030-worlds-selected-orbiter-stays-visible-and-framed">UXD-030</a>).</p><h2 id="back-to-explore" tabindex="-1">Back to Explore <a class="header-anchor" href="#back-to-explore" aria-label="Permalink to &quot;Back to Explore&quot;">​</a></h2><p>The first control of the view row is &quot;Back to Explore&quot; (<code>SurfaceScene</code>, <code>world_back_to_explore</code>; the first chip of <code>hud-top-mobile</code> on touch): a link to <code>/explore?id=earth</code>, where the Earth panel opens and the camera is on the planet (<a href="./decisions/UXD-028-explore-and-worlds-link-both-ways">UXD-028</a>, D5: an explicit link both ways, never a switch on zoom). It is the same chip on /moon, /mars and /venus (the Moon returns to <code>?id=earth:moon</code>, the satellite key). It hides with the rest of the row while a panorama is open or the flat ground patch is up; the nav&#39;s EXPLORE group stays.</p><h2 id="component-states" tabindex="-1">Component states <a class="header-anchor" href="#component-states" aria-label="Permalink to &quot;Component states&quot;">​</a></h2><p><strong>Object (default):</strong> dot with glow, label to the right <strong>Object (selected):</strong> larger dot, brighter glow, label bold, panel open <strong>Regime band (visible):</strong> subtle background colour fill, label right edge</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>Canvas: <code>aria-label=&quot;Earth orbit diagram on logarithmic scale from ISS at 408 km to JWST at 1.5 million km&quot;</code>.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><blockquote><p><strong>As-built note (2026-10-16):</strong> the boxes below were not maintained after implementation and are not a record of what shipped. For shipped behaviour see <a href="./../adr/TA"><code>docs/adr/TA.md</code></a> and <a href="./../../CHANGELOG"><code>CHANGELOG.md</code></a>.</p></blockquote><ul><li>[ ] ISS at bottom (~408 km), JWST near top (~1.5M km) — relative positions correct</li><li>[ ] Moon correctly positioned between cislunar region and L2</li><li>[ ] Geostationary belt at ~35,786 km</li><li>[ ] Regime labels visible and correctly positioned</li><li>[ ] Clicking any object opens detail panel</li><li>[ ] Detail panel shows altitude, orbital period, launch date, description</li></ul><hr><h2 id="extension-—-gallery-learn-tabs-v0-1-10" tabindex="-1">Extension — GALLERY + LEARN tabs (v0.1.10) <a class="header-anchor" href="#extension-—-gallery-learn-tabs-v0-1-10" aria-label="Permalink to &quot;Extension — GALLERY + LEARN tabs (v0.1.10)&quot;">​</a></h2><p>The detail panel gains a tab system: OVERVIEW (existing content) · GALLERY · LEARN. CSS sourced from the shared <code>src/lib/styles/panel-tabs.css</code> introduced in v0.1.10.</p><h3 id="layout-1" tabindex="-1">Layout <a class="header-anchor" href="#layout-1" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><ul><li>Tabs row sits below the agency-row + name + status header, above the existing data grid.</li><li>GALLERY tab renders only when <code>static/data/earth-object-galleries.json[id] &gt; 0</code>. LEARN tab renders only when the earth-object record has non-empty <code>links[]</code>.</li><li>DETAIL tab (<code>panel_tab_detail</code>, between GALLERY and LEARN) renders only when one of the object&#39;s <code>fleet_refs</code> names a craft with an anatomy drawing (9 objects: ISS, Tiangong, Hubble, Chandra, XMM-Newton, Clementine, Chang&#39;e 2, JWST, Gaia). Its body is headed &quot;The spacecraft&quot;: the drawing, its exploded cutaway when it has one, and the fleet link (<a href="./decisions/UXD-034-worlds-orbiter-detail-tab-and-panorama-opening">UXD-034</a>).</li><li>On <code>/iss</code> and <code>/tiangong</code> the assembly player keeps one box height in every phase (<a href="./decisions/UXD-031-station-assembly-player-fixed-box">UXD-031</a>, Design System 5.18).</li><li>Lightbox dimisses on click anywhere; localised aria-label <code>panel_lightbox_close</code>.</li></ul><h3 id="tokens-extension" tabindex="-1">Tokens (extension) <a class="header-anchor" href="#tokens-extension" aria-label="Permalink to &quot;Tokens (extension)&quot;">​</a></h3><p>Inherits all panel-tab tokens from UXS-004 §Extension. Active tab border: <code>#5070ff</code>. GALLERY thumb hover border: <code>rgba(80, 112, 255, 0.6)</code>. LEARN tier accent colors: muted blue <code>#889fe7</code> (intro) · blue (core) · gold (deep).</p><h3 id="acceptance-criteria-extension" tabindex="-1">Acceptance criteria (extension) <a class="header-anchor" href="#acceptance-criteria-extension" aria-label="Permalink to &quot;Acceptance criteria (extension)&quot;">​</a></h3><ul><li>[ ] OVERVIEW tab content (existing data grid + scale-fact + description + credit) unchanged</li><li>[ ] GALLERY tab renders when manifest count &gt; 0; thumbnail click opens lightbox</li><li>[ ] LEARN tab renders tiered intro/core/deep links from <code>earth-object.links</code></li><li>[ ] No GALLERY/LEARN tab when there&#39;s no data — never empty placeholders</li><li>[ ] DETAIL tab on the 9 objects with a drawing and on no other; &quot;The spacecraft&quot; heading; 0 critical or serious axe violations with it open (<code>a11y-orbiter-details.spec.ts</code>)</li></ul>`,47)])])}const u=a(n,[["render",r]]);export{b as __pageData,u as default};
